function fmt(n) {
  return String(Math.round(n * 100) / 100);
}

// 生成 CSV 文本（含 UTF-8 BOM，中文表头）
function buildCSV(values, result, exportedAt) {
  function cell(v) {
    var s = String(v);
    if (/[",\n\r]/.test(s)) return '"' + s.replace(/"/g, '""') + '"';
    return s;
  }
  var lines = [];
  lines.push(['正常工时(小时)', '加班工时(小时)', '时薪(元/小时)', '加班倍数',
              '正常工时费(元)', '加班工时费(元)', '应付总金额(元)'].map(cell).join(','));
  lines.push([
    fmt(values.normalHours), fmt(values.overtimeHours), fmt(values.rate), fmt(values.multiplier),
    (Math.round(result.normal * 100) / 100).toFixed(2),
    (Math.round(result.overtime * 100) / 100).toFixed(2),
    (Math.round(result.total * 100) / 100).toFixed(2)
  ].map(cell).join(','));
  lines.push('');
  lines.push(['导出时间', exportedAt].map(cell).join(','));
  return '﻿' + lines.join('\r\n') + '\r\n';
}

function exportCSV() {
  var values = {};
  var allOk = true;
  FIELDS.forEach(function (f) {
    var res = parseNumber(document.getElementById(f.id).value);
    values[f.id] = res.value;
    if (!res.ok) allOk = false;
  });
  var status = document.getElementById('status');
  if (!allOk) {
    status.textContent = '存在非法输入，请先修正后再导出 CSV。';
    return;
  }
  var result = computePay(values.normalHours, values.overtimeHours, values.rate, values.multiplier);
  var now = new Date();
  var pad = function (n) { return String(n).length < 2 ? '0' + n : String(n); };
  var stamp = now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate()) +
              ' ' + pad(now.getHours()) + ':' + pad(now.getMinutes()) + ':' + pad(now.getSeconds());
  var csv = buildCSV(values, result, stamp);
  var blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url;
  a.download = '工时计费_' + now.getFullYear() + pad(now.getMonth() + 1) + pad(now.getDate()) + '_' + pad(now.getHours()) + pad(now.getMinutes()) + '.csv';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(function () { URL.revokeObjectURL(url); }, 0);
  status.textContent = '已导出 CSV 文件（UTF-8 BOM，中文表头）。';
}

